\begin{corollary}
\label{cor:exact-integral-zero}
\uses{UNRESOLVED:ch16:16.13}
\dcref{chB:B.22}

Suppose $M$ is a compact oriented smooth $n$-manifold (without boundary). Then the integral of every exact $n$-form on $M$ is zero.
\end{corollary}

